src='/root/data/workbook.xlsx'
out='/root/output/result.xlsx'
orig=load_workbook(src, data_only=False)
res=load_workbook(out, data_only=False)
print('Reopened:', out)
print('Sheet names:', res.sheetnames)
print('Sheet names match original:', res.sheetnames == orig.sheetnames)
ws=res['Task']
ows=orig['Task']

# Verify target cells are formulas.
blocks = [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]
missing=[]
for r1,r2 in blocks:
    for r in range(r1,r2+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            if not (isinstance(v,str) and v.startswith('=')):
                missing.append(ws.cell(r,c).coordinate + ':' + repr(v))
print('All target cells contain formulas:', not missing)
if missing:
    print('Missing/non-formula:', missing)

# Verify non-target sheet dimensions not changed and Data sheet values unchanged in used region.
print('Task dimensions original/result:', ows.max_row, ows.max_column, '/', ws.max_row, ws.max_column)
print('Data dimensions original/result:', orig['Data'].max_row, orig['Data'].max_column, '/', res['Data'].max_row, res['Data'].max_column)

data_changed=[]
od=orig['Data']; rd=res['Data']
for r in range(1, max(od.max_row, rd.max_row)+1):
    for c in range(1, max(od.max_column, rd.max_column)+1):
        if od.cell(r,c).value != rd.cell(r,c).value:
            data_changed.append((r,c,od.cell(r,c).value,rd.cell(r,c).value))
print('Data sheet values unchanged:', not data_changed)

# Verify formatting in target cells preserved by comparing style IDs to original.
style_changed=[]
for r1,r2 in blocks:
    for r in range(r1,r2+1):
        for c in range(8,13):
            if ws.cell(r,c)._style != ows.cell(r,c)._style:
                style_changed.append(ws.cell(r,c).coordinate)
print('Target cell formatting unchanged:', not style_changed)
if style_changed:
    print('Style changed cells:', style_changed[:20], 'count', len(style_changed))

print('\nFormula strings from representative cells:')
for addr in ['H12','I13','L17','H19','J21','L24','H26','K30','L31','H35','I36','L40','H42','I43','J44','K45','L46','L47','H50','L50']:
    print(addr, ws[addr].value)

# Print full formula coverage compactly by block counts.
for r1,r2 in blocks:
    count=0
    for r in range(r1,r2+1):
        for c in range(8,13):
            if isinstance(ws.cell(r,c).value,str) and ws.cell(r,c).value.startswith('='):
                count += 1
    print(f'Block H{r1}:L{r2} formula count:', count, 'of', (r2-r1+1)*5)
